// ─── File: OutputTrapsDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.traps;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OutputTrapsDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountReferenceBuilder builder = new AccountReferenceBuilder();

        // TRAP 1: concat without reassignment leaves the original unchanged.
        String buggy = builder.buildBuggy("SAV", "2001");
        log.warning(() -> "buggy reference (concat not assigned) = '" + buggy + "'");

        // FIX: assign the result of concat.
        String fixed = builder.buildFixed("SAV", "2001");
        log.info(() -> "fixed reference = '" + fixed + "'");

        // TRAP 2: catch ordering — specific (NPE) BEFORE general (Exception).
        TransferHandler handler = new TransferHandler();
        handler.handle(null, new BigDecimal("50000"));              // triggers NPE branch
        handler.handle("SAV2001", new BigDecimal("-1"));            // triggers general branch
        handler.handle("SAV2001", new BigDecimal("50000"));         // success
    }
}

// ─── Would be in AccountReferenceBuilder.java ───
class AccountReferenceBuilder {
    // BUG: concat returns a NEW string that is thrown away; prefix is unchanged.
    String buildBuggy(String prefix, String number) {
        prefix.concat(number);  // result discarded — immutability trap
        return prefix;          // still just "SAV"
    }
    // FIX: capture the returned string.
    String buildFixed(String prefix, String number) {
        prefix = prefix.concat(number); // reassign
        return prefix;                  // "SAV2001"
    }
}

// ─── Would be in TransferHandler.java ───
class TransferHandler {
    private static final Logger log = Logger.getLogger("BankLog");

    void handle(String accountId, BigDecimal amount) {
        try {
            // May throw NullPointerException if accountId is null.
            int len = accountId.length();
            if (amount.signum() <= 0) {
                throw new IllegalArgumentException("amount must be positive");
            }
            log.info(() -> "transfer OK for " + accountId + " (idLen=" + len + ") Rs." + amount);

        // CORRECT ORDER: most specific subclass FIRST.
        } catch (NullPointerException e) {
            log.severe(() -> "accountId was null: " + e.getClass().getSimpleName());

        // General LAST. If these two were swapped it would NOT compile:
        //   catch (Exception e) { ... }           // would catch everything first
        //   catch (NullPointerException e) { ... } // ERROR: already been caught
        } catch (Exception e) {
            log.severe(() -> "transfer rejected: " + e.getMessage());
        }
    }
}
